//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_request_sample(value: *mut Drone_Lifecycle_Governor::Lifecycle_Request_Sample) -> bool;
  fn put_qualified_request(value: *mut Drone_Lifecycle_Governor::Qualified_Request) -> bool;
}

pub fn unsafe_get_request_sample() -> Drone_Lifecycle_Governor::Lifecycle_Request_Sample
{
  unsafe {
    let value: *mut Drone_Lifecycle_Governor::Lifecycle_Request_Sample = &mut Drone_Lifecycle_Governor::Lifecycle_Request_Sample::default();
    get_request_sample(value);
    return *value;
  }
}

pub fn unsafe_put_qualified_request(value: &Drone_Lifecycle_Governor::Qualified_Request) -> bool
{
  unsafe {
    return put_qualified_request(value as *const Drone_Lifecycle_Governor::Qualified_Request as *mut Drone_Lifecycle_Governor::Qualified_Request);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_request_sample: Mutex<Option<Drone_Lifecycle_Governor::Lifecycle_Request_Sample>> = Mutex::new(None);
  pub static ref OUT_qualified_request: Mutex<Option<Drone_Lifecycle_Governor::Qualified_Request>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_request_sample.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_qualified_request.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_request_sample(value: *mut Drone_Lifecycle_Governor::Lifecycle_Request_Sample) -> bool
{
  unsafe {
    let guard = IN_request_sample.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_qualified_request(value: *mut Drone_Lifecycle_Governor::Qualified_Request) -> bool
{
  unsafe {
    *OUT_qualified_request.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
